export function publicPhotoUri(name) {
    return `public-photo:${name}`;
}

export function itemImageSource(uri) {
    if (uri?.startsWith("public-photo:")) {
        return PUBLIC_PHOTOS.find((photo) => photo.name === uri.slice(13))?.source;
    }
    return { uri };
}
